WITH flattened_attrs AS (SELECT id, customer_id, created_at, items, ship_to, EXISTS(items, item -> item.price > 100) AS has_premium_item, SIZE(FILTER(items, item -> item.qty >= 3)) AS bulk_lines, ship_to.zip AS ship_zip, attributes['utm_source'] AS utm_source, COALESCE(attributes['gift'], 'direct') AS gift_or_default FROM carts) SELECT id, customer_id, created_at, bulk_lines, gift_or_default, COUNT(bulk_lines) OVER (PARTITION BY customer_id ORDER BY bulk_lines, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_count_bulk_lines, AVG(bulk_lines) OVER (PARTITION BY customer_id ORDER BY bulk_lines, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_avg_bulk_lines, MAX(bulk_lines) OVER (PARTITION BY customer_id ORDER BY bulk_lines, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_max_bulk_lines, SUM(bulk_lines) OVER (PARTITION BY customer_id ORDER BY bulk_lines, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_sum_bulk_lines, AVG(bulk_lines) OVER (PARTITION BY customer_id ORDER BY bulk_lines, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS bulk_lines_avg_6 FROM flattened_attrs
